void UAnimV1::DalOnPlayMontageNotifyBegin(FName DalNotifyName, const FBranchingPointNotifyPayload& DalPayload)
{
	const int32 DalId = DalFindNotifyId(DalNotifyName);
	if (DalId == INDEX_NONE)
	{
		return;
	}

	// a notify window (PlayMontageNotifyWindow) is a state; a PlayMontageNotify is a point
	const bool bDalWindow = DalPayload.NotifyEvent != nullptr && DalPayload.NotifyEvent->NotifyStateClass != nullptr;
	DalHost::FEvent DalEvent;
	DalEvent.Kind = bDalWindow ? DalHost::EEventKind::NotifyBegin : DalHost::EEventKind::Notify;
	DalEvent.Id = DalId;
	DalPostEvent(DalEvent);
}

void UAnimV1::DalOnPlayMontageNotifyEnd(const FName DalNotifyName, [[maybe_unused]] const FBranchingPointNotifyPayload& DalPayload)
{
	const int32 DalId = DalFindNotifyId(DalNotifyName);
	if (DalId != INDEX_NONE)
	{
		DalHost::FEvent DalEvent;
		DalEvent.Kind = DalHost::EEventKind::NotifyEnd;
		DalEvent.Id = DalId;
		DalPostEvent(DalEvent);
	}
}

void UAnimV1::DalDispatchEvents()
{
	for (const DalHost::FEvent& DalEvent : DalFrameEvents)
	{
		// on notify HitNotify
		if (DalEvent.Kind == DalHost::EEventKind::Notify && DalEvent.Id == Dal_NotifyId_HitNotify)
		{
			DalHandler_0();
		}
		// on notify_begin Window
		if (DalEvent.Kind == DalHost::EEventKind::NotifyBegin && DalEvent.Id == Dal_NotifyId_Window)
		{
			DalHandler_1();
		}
		// on notify_end Window
		if (DalEvent.Kind == DalHost::EEventKind::NotifyEnd && DalEvent.Id == Dal_NotifyId_Window)
		{
			DalHandler_2();
		}
		// on montage_ended Slash
		if (DalEvent.Kind == DalHost::EEventKind::MontageEnded && DalEvent.Id == Dal_MontageId_Slash)
		{
			DalHandler_3(DalEvent.bFlag);
		}
		// on montage_blending_out Slash
		if (DalEvent.Kind == DalHost::EEventKind::MontageBlendingOut && DalEvent.Id == Dal_MontageId_Slash)
		{
			DalHandler_4(DalEvent.bFlag);
		}
	}
	DalFrameEvents.Reset();
}

void UAnimV1::DalHandler_0()
{
	Count = Count + 1;
	DalEnqueue(DalHost::Cmd::SetGravityScale(2.0f));
}

void UAnimV1::DalHandler_1()
{
	Open = true;
}

void UAnimV1::DalHandler_2()
{
	Open = false;
}

void UAnimV1::DalHandler_3([[maybe_unused]] const bool interrupted)
{
	Ended = Ended + 1;
	if (interrupted)
	{
		DalEnqueue(DalHost::Cmd::Jump());
	}
}

void UAnimV1::DalHandler_4([[maybe_unused]] const bool interrupted)
{
	Blend = Blend + 1;
}

void UAnimV1::DalUpdate([[maybe_unused]] const float dt)
{
	DalDispatchEvents();
	if ((Fired > 0.5f) && (!DalMontage_Slash_playing))
	{
		DalEnqueue(DalHost::Cmd::MontagePlay(Dal_MontageId_Slash, 1.0f, static_cast<int32>(ESlashSection::Hit)));
	}
	Phase = DalMontage_Slash_section;
	Pos = DalMontage_Slash_position;
	WasPlaying = DalMontage_Slash_playing;
	if (DalMontage_Slash_active && (Pos > 1.5f))
	{
		DalEnqueue(DalHost::Cmd::MontageSetNextSection(Dal_MontageId_Slash, static_cast<int32>(ESlashSection::Hit), static_cast<int32>(ESlashSection::Rec)));
	}
}

void UAnimV1::Kick()
{
	[[maybe_unused]] const float dt = Dal_DeltaSeconds;
	DalEnqueue(DalHost::Cmd::MontageStop(Dal_MontageId_Slash, -1.0f));
}

